SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'H'), 'circularity_aspects', 'Zirkularitätsaspekte (§3.6.1, Mehrfachauswahl)', 'json', NULL, false, '§3.6.1', 'Plan 3: Mehrfachauswahl über die fünf in §3.6.1 als EXAMPLE gedruckten Zirkularitätsaspekte (Durability, recyclability, reusability, repairability, recoverability); das bestehende Freitextfeld circularity_aspect bleibt (iso59004-D-10, Vererbung nach -05/-06 unverändert). Die Liste ist ein Beispiel, keine abgeschlossene Aufzählung (iso59004-U-3).', 'imported_unverified', 'element of an organization’s (3.4.1) activities or solutions (3.2.1) that interacts with the circular economy (3.1.1) EXAMPLE Durability, recyclability, reusability, repairability, recoverability. — PDF p.20 (gedruckte S. 13), §3.6.1', 'select_many', '{"title":"Zirkularitätsaspekte (§3.6.1)","subtitle":"Die fünf in §3.6.1 als EXAMPLE gedruckten Aspekte ankreuzen — Definition: „element of an organization’s (3.4.1) activities or solutions (3.2.1) that interacts with the circular economy (3.1.1)“","allow_custom":true,"note":"element of an organization’s (3.4.1) activities or solutions (3.2.1) that interacts with the circular economy (3.1.1) EXAMPLE Durability, recyclability, reusability, repairability, recoverability. — iso59004-U-3: Die fünf Aspekte sind als EXAMPLE gedruckt, nicht als abgeschlossene Liste; das Freitextfeld circularity_aspect bleibt für alles Weitere (iso59004-D-10). Dieselbe Liste ist in ISO-59020 ein Enum — Vererbung ist Phase 6 (iso59004-X-1).","groups":[{"label":"§3.6.1 EXAMPLE","options":["durability","recyclability","reusability","repairability","recoverability"]}]}'::jsonb, NULL, NULL, '[{"value":"durability","label_de":"Dauerhaftigkeit (durability)","order_index":1},{"value":"recyclability","label_de":"Recyclingfähigkeit (recyclability)","order_index":2},{"value":"reusability","label_de":"Wiederverwendbarkeit (reusability)","order_index":3},{"value":"repairability","label_de":"Reparierbarkeit (repairability)","order_index":4},{"value":"recoverability","label_de":"Rückgewinnbarkeit (recoverability)","order_index":5}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'circularity_aspects') AND w.code = 'ISO-59004-02' AND s.code = 'ISO-59004';
