SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'principles', 'Berücksichtigte Grundsätze (§5.2.1 – §5.2.6, Mehrfachauswahl)', 'json', NULL, false, '§5.1, §5.2, §5.3.2', 'Plan 3: Mehrfachauswahl über die sechs gedruckten Grundsätze (Token = prod selected_principle = Zeilenschlüssel der Tabelle S5_2); das Einzelfeld selected_principle und das Pflicht-Boolean all_principles_considered bleiben (iso59004-D-9). all_principles_considered_code ist ZURÜCKGEHALTEN (iso59004-F-1 — contains() über einen json-Träger hat seit Plan 3 Welle A einen Motorpfad; der Block bleibt bis zur Ratifizierung zurückgehalten).', 'imported_unverified', 'The set of principles given in 5.2, which are interlinked and complementary, should be considered by an organization to transition towards a circular economy. — Considering the integration of all the circular economy principles is important, as focusing on only one or two principles can undermine the achievements that would otherwise occur if all the principles were considered. — PDF pp.22–23 (gedruckte S. 15–16), §5.1 / §5.3.2', 'select_many', '{"title":"Grundsätze (§5.2)","subtitle":"„The set of principles given in 5.2, which are interlinked and complementary, should be considered by an organization to transition towards a circular economy.“ — alle sechs ankreuzen, die berücksichtigt wurden","note":"Considering the integration of all the circular economy principles is important, as focusing on only one or two principles can undermine the achievements that would otherwise occur if all the principles were considered. — Das Einzelfeld selected_principle (eine Auswahl von sechs) und das Hand-Boolean all_principles_considered (CR-013, Pflichtfeld) bleiben (iso59004-D-9); ein Vollständigkeits-Code über diese Liste ist noch nicht codiert — Entscheidung auf dem Sign-off-Bogen (iso59004-F-1).","groups":[{"label":"§5.2.1 – §5.2.6","options":["systems_thinking","value_creation","value_sharing","resource_stewardship","resource_traceability","ecosystem_resilience"]}]}'::jsonb, NULL, NULL, '[{"value":"systems_thinking","label_de":"Systemdenken","order_index":1},{"value":"value_creation","label_de":"Wertschoepfung","order_index":2},{"value":"value_sharing","label_de":"Wertteilung","order_index":3},{"value":"resource_stewardship","label_de":"Ressourcenverantwortung","order_index":4},{"value":"resource_traceability","label_de":"Ressourcenrueckverfolgbarkeit","order_index":5},{"value":"ecosystem_resilience","label_de":"Oekosystem-Resilienz","order_index":6}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'principles') AND w.code = 'ISO-59004-04' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'actions', 'Maßnahmenregister (je Maßnahme: R-Strategie, Kategorie, Machbarkeit, Pilot, Wertschöpfungsmodell, Lebenszyklus-Notiz)', 'json', NULL, false, '§6.1, §6.7, Table 1', 'Plan 3: Zeilen je Maßnahme der Kreislaufwirtschaft — ersetzt die Ein-Maßnahme-Einzelfelder der Arbeitsblätter -05/-06 durch die N-Instanzen-Form. Anzahl → actions_count (ISO-59004-05-D1), refuse/rethink → refuse_rethink_first (-D2), Pilotmaßnahmen → pilot_actions_count (-D3). Die Einzelfelder bleiben (iso59004-D-1 … D-6); Tabelle 1 ist nicht geseedet (iso59004-U-1).', 'imported_unverified', 'This resource management guidance is intended to help organizations prioritize actions to increase circularity performance. A life cycle perspective should guide the organization in the identification of the best action for their value creation model and to avoid unwanted trade-offs. — Organizations should consider refuse and rethink as preliminary actions. — PDF pp.25, 34 (gedruckte S. 18, 27), §6.1 / §6.7', 'register', '{"title":"Maßnahmen der Kreislaufwirtschaft (§6.7, Tabelle 1)","subtitle":"Je Maßnahme eine Zeile: R-Strategie, Kategorie nach §6.2 – §6.6, Machbarkeitsdimensionen (§7.4.5), Pilot (§7.4.7), Lebenszyklus-Notiz (§6.7) und Wertschöpfungsmodell (§7.4.4)","add_label":"+ Maßnahme","placement":"section","columns":[{"key":"action","label":"R-Strategie (Tabelle 1)","type":"enum","required":true,"discriminator":true,"options":["refuse","rethink","source","reduce","repair","re_use","refurbish","remanufacture","repurpose","cascade","recycle","recover_energy","re_mine"],"option_labels":{"refuse":"Verweigern","rethink":"Ueberdenken","source":"Beziehen","reduce":"Reduzieren","repair":"Reparieren","re_use":"Wiederverwenden","refurbish":"Aufarbeiten","remanufacture":"Wiederaufbereiten","repurpose":"Umnutzen","cascade":"Kaskadieren","recycle":"Recyceln","recover_energy":"Energie zurueckgewinnen","re_mine":"Rueckgewinnen aus Deponien"},"aria_label":"Gewählte Maßnahme nach Tabelle 1 (refuse … re-mine)"},{"key":"category","label":"Kategorie (§6.2 – §6.6)","type":"enum","options":["create_added_value","value_retention","value_recovery","regenerate_ecosystems","support_transition"],"option_labels":{"create_added_value":"Wertschaffung (§6.2)","value_retention":"Werterhaltung (§6.3)","value_recovery":"Wertrueckgewinnung (§6.4)","regenerate_ecosystems":"Oekosystem-Regeneration (§6.5)","support_transition":"Transformationsunterstuetzung (§6.6)"},"aria_label":"Maßnahmenkategorie nach §6.2 bis §6.6"},{"key":"feasibility_dimensions","label":"Machbarkeitsdimensionen (§7.4.5)","type":"text","datalist":["Technisch","Organisatorisch","Finanziell & wirtschaftlich","Kontext","Sozial","Umweltbezogen"],"aria_label":"Gegen welche der sechs gedruckten Dimensionen die Maßnahme bewertet wurde"},{"key":"pilot","label":"Pilot (§7.4.7)","type":"boolean","aria_label":"Maßnahme wird zunächst als Pilot umgesetzt"},{"key":"value_creation_model","label":"Wertschöpfungsmodell (§7.4.4)","type":"text","aria_label":"Zur Maßnahme gehörendes Wertschöpfungsmodell"},{"key":"life_cycle_note","label":"Lebenszyklus-Notiz (§6.7)","type":"text","aria_label":"Begründung der Maßnahmenwahl aus der Lebenszyklusperspektive"},{"key":"preliminary","label":"Vorläufige Maßnahme","type":"derived","expr":"if(action == ''refuse'' OR action == ''rethink'', 1, 0)","display":"badge","value_labels":{"0":"","1":"§6.1: refuse / rethink — vorläufige Maßnahme"}}],"footer":["actions_count","refuse_rethink_first","pilot_actions_count"],"note":"This resource management guidance is intended to help organizations prioritize actions to increase circularity performance. A life cycle perspective should guide the organization in the identification of the best action for their value creation model and to avoid unwanted trade-offs. In general, products should be repaired before they are remanufactured, and remanufactured before they are recycled. However, in cases where applying this guidance does not lead to the best outcome, organizations should consider applying a life cycle perspective to determine the best action. — iso59004-U-1: Tabelle 1 ist NICHT geseedet (keine gedruckte Kategoriespalte; die beiden gedruckten Spalten verschränken sich in der Extraktion), daher wird „Kategorie“ vom Ingenieur gesetzt und nicht aus der Tabelle gefüllt. Die Einzelfelder selected_action / action_category / feasibility_dimension / pilot_project / value_creation_model / life_cycle_perspective_applied bleiben (iso59004-D-1 … D-6). Die Lebenszyklus-Notiz ist IMMER sichtbar (iso59004-J-3). Machbarkeitsdimensionen sind Freitext mit Vorschlagsliste — eine Mehrfachauswahl je Zeile kennt der Registervertrag nicht (iso59004-I-1)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'actions') AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'actions_count', 'Anzahl erfasster Maßnahmen', 'number', NULL, false, '§6.7', 'Plan 3: Ausgabe der Gleichung ISO-59004-05-D1 — count_rows über actions.', 'imported_unverified', 'The guidance (see Table 1) suggests organizations can begin by determining if there is a need to be satisfied and if the need can be met without additional resource use (refuse). If a solution is needed, the guidance suggests that organizations begin with a systemic approach, re-evaluating the concept from the earliest possible stages by designing solutions that use fewer resources (rethink, reduce) and prioritizing the use of recovered resources and sustainably produced renewable resources (source). Organizations should seek to extend the life of solutions by design and by maintaining the solution in use for as long as possible (repair, reuse, refurbish, remanufacture, repurpose) while continuing to provide value. Finally, organizations should look to use resources in multiple cycles (cascade, recycle), recover the energy if the resource cannot be used again (energy recovery) or source resources from landfills (re-mine). — PDF p.34 (gedruckte S. 27), §6.7', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'actions_count') AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'refuse_rethink_first', 'Maßnahmen der Stufen refuse / rethink (§6.1 vorläufige Maßnahmen)', 'number', NULL, false, '§6.1', 'Plan 3: Ausgabe der Gleichung ISO-59004-05-D2 — Zeilen mit action refuse oder rethink („Organizations should consider refuse and rethink as preliminary actions.“); Zwilling des Hand-Booleans preliminary_action_refuse_rethink (CR-018, iso59004-D-11) — die Gate-Umstellung ist STAGED (iso59004-G-2).', 'imported_unverified', 'Organizations should consider refuse and rethink as preliminary actions. — PDF p.25 (gedruckte S. 18), §6.1', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'refuse_rethink_first') AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'pilot_actions_count', 'Als Pilot geplante Maßnahmen (§7.4.7)', 'number', NULL, false, '§7.4.7', 'Plan 3: Ausgabe der Gleichung ISO-59004-05-D3 — Zeilen mit pilot == true; Zwilling des Booleans pilot_project auf -06 (iso59004-D-4).', 'imported_unverified', 'Prior to formal implementation some organizations can consider a preliminary pilot application of a specific circular economy practice or for a specific segment of the organization to ensure the application works as planned and any specific risk or barriers are addressed before wider implementation. This allows organizations to review practical viability and effectiveness of the proposed areas of strategies and actions, and alignment with the circular economy principles, and to prove effectiveness in achieving its goals. — PDF p.42 (gedruckte S. 35), §7.4.7', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pilot_actions_count') AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'life_cycle_justification', 'Begründung der Abweichung von reparieren → wiederaufbereiten → recyceln (§6.7)', 'text', NULL, false, '§6.7', 'Plan 3: „However, in cases where applying this guidance does not lead to the best outcome, organizations should consider applying a life cycle perspective to determine the best action.“ — nur sichtbar, wenn repair_before_remanufacture_before_recycle ausdrücklich false ist (unbesetzt ⇒ pending ⇒ sichtbar, ausfallsicher). Die passende Gate-Umschrift von CR-028 (IF … == false THEN life_cycle_justification IS NOT NULL) ist STAGED (iso59004-G-1).', 'imported_unverified', 'In general, products should be repaired before they are remanufactured, and remanufactured before they are recycled. However, in cases where applying this guidance does not lead to the best outcome, organizations should consider applying a life cycle perspective to determine the best action. — PDF p.35 (gedruckte S. 28), §6.7', 'scalar', NULL, NULL, 'repair_before_remanufacture_before_recycle == false', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'life_cycle_justification') AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'goals', 'Zielregister (je Ziel: Ziel, Zwischenziel, Zieljahr, Indikator)', 'json', NULL, false, '§7.3.2', 'Plan 3: Zeilen je Ziel der Kreislaufwirtschaft mit Zwischenziel und Zieljahr („goals with an aim to create structured and lasting change“ / „Intermediate targets should be established“); Anzahl → goals_count (ISO-59004-06-D1), Ziele mit Zwischenziel → goals_with_targets (-D2). Das Freitextfeld ce_goals bleibt (iso59004-D-7).', 'imported_unverified', 'The organization should develop goals with an aim to create structured and lasting change and identify pathways and key actions to achieve their vision for a circular economy. Intermediate targets should be established to allow for circularity assessments of progress from the reference situation towards the longer- term goals. — PDF p.40 (gedruckte S. 33), §7.3.2', 'register', '{"title":"Ziele der Kreislaufwirtschaft mit Zwischenzielen (§7.3.2)","subtitle":"„Intermediate targets should be established to allow for circularity assessments of progress from the reference situation towards the longer-term goals.“ — je Ziel eine Zeile","add_label":"+ Ziel","placement":"section","columns":[{"key":"goal","label":"Ziel","type":"text","required":true,"aria_label":"Ziel der Kreislaufwirtschaft"},{"key":"intermediate_target","label":"Zwischenziel","type":"text","aria_label":"Zwischenziel zu diesem Ziel"},{"key":"year","label":"Zieljahr","type":"number","aria_label":"Jahr, für das das Zwischenziel gilt"},{"key":"indicator","label":"Indikator","type":"text","aria_label":"Indikator, an dem der Fortschritt gemessen wird"}],"footer":["goals_count","goals_with_targets"],"note":"The organization should develop goals with an aim to create structured and lasting change and identify pathways and key actions to achieve their vision for a circular economy. Intermediate targets should be established to allow for circularity assessments of progress from the reference situation towards the longer- term goals. Das Freitextfeld ce_goals (Pflichtfeld, CR-035) bleibt (iso59004-D-7). „Zwischenziel gesetzt“ zählt über IS NOT NULL: ein leerer Text zählt NICHT (in dieser Sitzung am Motor geprüft — der Vergleich != '''' liefert manual_required, siehe iso59004-J-5)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'goals') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'goals_count', 'Anzahl erfasster Ziele', 'number', NULL, false, '§7.3.2', 'Plan 3: Ausgabe der Gleichung ISO-59004-06-D1 — count_rows über goals.', 'imported_unverified', 'The organization should develop goals with an aim to create structured and lasting change and identify pathways and key actions to achieve their vision for a circular economy. Intermediate targets should be established to allow for circularity assessments of progress from the reference situation towards the longer- term goals. — PDF p.40 (gedruckte S. 33), §7.3.2', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'goals_count') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'goals_with_targets', 'Ziele mit hinterlegtem Zwischenziel (§7.3.2)', 'number', NULL, false, '§7.3.2', 'Plan 3: Ausgabe der Gleichung ISO-59004-06-D2 — Zeilen, deren Zwischenziel gesetzt ist (IS NOT NULL; ein leerer Text zählt nicht — iso59004-J-5).', 'imported_unverified', 'The organization should develop goals with an aim to create structured and lasting change and identify pathways and key actions to achieve their vision for a circular economy. Intermediate targets should be established to allow for circularity assessments of progress from the reference situation towards the longer- term goals. — PDF p.40 (gedruckte S. 33), §7.3.2', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'goals_with_targets') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'indicators_59004', 'Indikatorregister (je Indikator: Bezeichnung, Ausgangswert, Zielwert)', 'json', NULL, false, '§7.6', 'Plan 3: Zeilen je gewähltem Zirkularitätsindikator mit Ausgangswert und Zielwert („can include milestones and targets for the next period“); Anzahl → indicators_59004_count (ISO-59004-06-D3). Das Freitextfeld selected_circularity_indicator bleibt (iso59004-D-8); die Bindung an ISO-59020 Tabelle 3 ist Phase 6 (iso59004-X-1).', 'imported_unverified', 'As part of its action plan for a circular economy (see 7.1.4), the organization should choose circularity indicators to assess the effectiveness and efficiency of the interventions adopted and monitor the progress. The circularity indicators should be determined with the circular economy principles in mind, as well as the circularity goals and strategic priorities established by the organization. Guidance on how to measure and assess circularity performance is provided by ISO 59020. — PDF p.43 (gedruckte S. 36), §7.6', 'register', '{"title":"Zirkularitätsindikatoren mit Ausgangswert und Zielwert (§7.6)","subtitle":"„the organization should choose circularity indicators to assess the effectiveness and efficiency of the interventions adopted and monitor the progress“ — je Indikator eine Zeile","add_label":"+ Indikator","placement":"section","columns":[{"key":"indicator","label":"Indikator","type":"text","required":true,"aria_label":"Bezeichnung des Zirkularitätsindikators"},{"key":"baseline","label":"Ausgangswert","type":"number","aria_label":"Ausgangswert des Indikators in der Referenzsituation"},{"key":"target","label":"Zielwert","type":"number","aria_label":"Zielwert des Indikators für die nächste Periode"}],"footer":["indicators_59004_count"],"note":"As part of its action plan for a circular economy (see 7.1.4), the organization should choose circularity indicators to assess the effectiveness and efficiency of the interventions adopted and monitor the progress. The circularity indicators should be determined with the circular economy principles in mind, as well as the circularity goals and strategic priorities established by the organization. Guidance on how to measure and assess circularity performance is provided by ISO 59020. Review of the circularity indicators and circularity performance should set the basis for continual improvement and, therefore, can include milestones and targets for the next period. These elements are confirmed by relevant interested parties, whose expectations are identified through enhanced dialogue and communication processes. Das Freitextfeld selected_circularity_indicator (Pflichtfeld) bleibt (iso59004-D-8). Die MESSUNG selbst liegt bei ISO 59020 („Guidance on how to measure and assess circularity performance is provided by ISO 59020.“) — die Verknüpfung mit den Tabelle-3-Indikatoren von ISO-59020 ist Phase 6 (iso59004-X-1), daher hier Freitext und kein lookup_key."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'indicators_59004') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'indicators_59004_count', 'Anzahl erfasster Zirkularitätsindikatoren', 'number', NULL, false, '§7.6', 'Plan 3: Ausgabe der Gleichung ISO-59004-06-D3 — count_rows über indicators_59004.', 'imported_unverified', 'As part of its action plan for a circular economy (see 7.1.4), the organization should choose circularity indicators to assess the effectiveness and efficiency of the interventions adopted and monitor the progress. The circularity indicators should be determined with the circular economy principles in mind, as well as the circularity goals and strategic priorities established by the organization. Guidance on how to measure and assess circularity performance is provided by ISO 59020. — PDF p.43 (gedruckte S. 36), §7.6', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'indicators_59004_count') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'operates_across_multiple_levels', 'Organisation wirkt über mehr als eine Systemebene (§7.1.3)', 'boolean', NULL, false, '§7.1.3', 'Plan 3: Treiber für die Beziehungen zwischen den Systemebenen („Organizations that interact or operate across more than one system level should consider the relationships and interactions within and between the other system levels to achieve a circular economy.“). Das bestehende Enum implementation_level hat KEINEN Mehrebenen-Token (vier Token: global_regional_country_local / interorganizational / organizational / product) — deshalb ein eigenes Boolean statt einer erfundenen Option (iso59004-J-6).', 'imported_unverified', 'Organizations that interact or operate across more than one system level should consider the relationships and interactions within and between the other system levels to achieve a circular economy. — PDF p.36 (gedruckte S. 29), §7.1.3', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'operates_across_multiple_levels') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'level_relationships', 'Beziehungen und Wechselwirkungen zwischen den Systemebenen (§7.1.3)', 'text', NULL, false, '§7.1.3', 'Plan 3: nur sichtbar, wenn operates_across_multiple_levels == true (unbesetzt ⇒ pending ⇒ sichtbar, ausfallsicher). Die passende Umschrift von CR-031 ist STAGED (iso59004-G-3).', 'imported_unverified', 'Organizations that interact or operate across more than one system level should consider the relationships and interactions within and between the other system levels to achieve a circular economy. — PDF p.36 (gedruckte S. 29), §7.1.3', 'scalar', NULL, NULL, 'operates_across_multiple_levels == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'level_relationships') AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004';
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'selected_principle' AND w.code = 'ISO-59004-04' AND s.code = 'ISO-59004' AND f.active;
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'selected_action' AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004' AND f.active;
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'action_category' AND w.code = 'ISO-59004-05' AND s.code = 'ISO-59004' AND f.active;
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'implementation_stage' AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004' AND f.active;
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'implementation_level' AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004' AND f.active;
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'feasibility_dimension' AND w.code = 'ISO-59004-06' AND s.code = 'ISO-59004' AND f.active;
COMMIT;
